  box-shadow: inset 0 0 0 1px rgba(255,255,255,.1);
}

[data-viewers="row"] {
  gap: 0 !important;
  align-items: stretch !important;
}

[data-viewers="icon"] {
  display: flex;
  align-items: center;
  padding: 0 .4em;
  background: var(--viewers-accent, var(--color));
  color: var(--on-color) !important;
}

[data-viewers="count"] {
  display: flex;
  align-items: center;
  padding: .25em .55em;
  letter-spacing: .08em;
}

:scope {
  --color: var(--overlay-accent, #ffffff); /* Colour */
  --on-color: #0a0a0b; /* Text on the colour */
  --ground: #0a0a0b; /* The black it sits on */
  --cell: #141416; /* The raised cell */
  --edge: 3px; /* Coloured edge */
}

[data-omnibar="bar"] {
  background: var(--omnibar-background, var(--ground)) !important;
  border-top: var(--edge) solid var(--omnibar-accent, var(--color));
  gap: 0 !important;
  padding: 0 !important;
}

[data-omnibar="slot"] {
  align-items: stretch !important;
  height: 100%;
  gap: 0 !important;
  flex: 1 1 auto;
}

[data-omnibar-state="pinned"] { flex: 0 0 auto; }

[data-omnibar="label"] {
  display: flex;
  align-items: center;
  padding: 0 20px;
  background: var(--omnibar-accent, var(--color));
  color: var(--on-color) !important;
  letter-spacing: .2em;
}

[data-omnibar="value"] {
  display: flex;
  align-items: center;
  padding: 0 24px;
  background: var(--cell);
  border-right: 1px solid rgba(255,255,255,.12);
  letter-spacing: .08em;
  flex: 1 1 auto;
}
